CREATE DATABASE IF NOT EXISTS campusfind CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE campusfind;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,regno VARCHAR(60) NOT NULL UNIQUE,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('student','admin') NOT NULL DEFAULT 'student',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS items(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,kind ENUM('lost','found') NOT NULL,name VARCHAR(180) NOT NULL,category VARCHAR(100) NOT NULL,location VARCHAR(180) NOT NULL,item_date DATE NOT NULL,item_time TIME NULL,description TEXT NOT NULL,photo MEDIUMTEXT NULL,finder VARCHAR(120) NULL,status ENUM('lost','found','claimed','collected') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS claims(id BIGINT AUTO_INCREMENT PRIMARY KEY,item_id BIGINT NOT NULL,claimant_id INT NOT NULL,details TEXT NOT NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',reviewed_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,reviewed_at DATETIME NULL,FOREIGN KEY(item_id) REFERENCES items(id),FOREIGN KEY(claimant_id) REFERENCES users(id),FOREIGN KEY(reviewed_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notifications(id BIGINT AUTO_INCREMENT PRIMARY KEY,item_id BIGINT NOT NULL,user_id INT NOT NULL,kind VARCHAR(40) NOT NULL,message TEXT NOT NULL,read_at DATETIME NULL,sent_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(item_id) REFERENCES items(id),FOREIGN KEY(user_id) REFERENCES users(id),INDEX idx_user_notice(user_id,sent_at));
